python3 << 'EOF'
import json
import pandas as pd

with open('output/itinerary.json') as f:
    data = json.load(f)

df_attr = pd.read_csv('data/attractions/attractions.csv')
valid_attr_names = set(df_attr['Name'].tolist())

# Check each day has non-empty attractions
for day in data['plan']:
    a = day['attraction']
    if a == '-' or not a.strip() or not a.endswith(';'):
        print(f"Day {day['day']}: BAD attraction: '{a}'")
    else:
        for name in a.split(';'):
            if not name:
                continue
            if name not in valid_attr_names:
                print(f"Day {day['day']}: ATTRACTION NOT IN DATA: '{name}'")
            else:
                pass
        print(f"Day {day['day']}: OK - {a}")

# Also check no flights
for day in data['plan']:
    if 'flight' in str(day['transportation']).lower():
        print(f"ERROR: Flight detected on day {day['day']}")
EOF

